`timescale 1ns/1ns
module right_shifter_tb;

// === Global Sync Signal ===
reg llm_go_signal = 1;

  reg clk;
  reg d;
  wire [7:0] q;

  // Instantiate the DUT (Design Under Test)
  right_shifter dut (
    .clk(clk),
    .d(d),
    .q(q)
  );

  // Generate clock
  always #5 clk = ~clk;

  initial begin
    // Initialize inputs
    clk = 0;
    d = 0;
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

    #20;
    d = 1;
    #10;
    d = 0;
    #10;
    d = 1;
    #10;
    d = 0;
    #10;
    d = 1;
    #10;
    d = 1;
    #10;
    d = 1;
    #10;

    // Check the output
    if(q==8'b11101010) begin
      $display("===========Your Design Passed===========");
    end
    else begin
      $display("===========Failed===========");
    end
    // Finish simulation
    $finish;
  end




        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "q,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", q);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting deterministic mutation test vectors...");

    // Initialize input d to known state
    d = 0;

    // Wait for clock to stabilize (sync to negedge to drive inputs for posedge)
    repeat(5) @(negedge clk);

    // ---------------------------------------------------------
    // Test Case 1: Walking 1
    // Objective: Verify Shift Right (>>) vs Left (<<) and Insertion at MSB (q[7])
    // ---------------------------------------------------------
    // Drive d=1 for one cycle. Expected q next: 8'h80
    d = 1;
    @(negedge clk);

    // Drive d=0 and observe the '1' shifting right to LSB.
    // Expected q sequence: 80 -> 40 -> 20 -> 10 -> 08 -> 04 -> 02 -> 01 -> 00
    d = 0;
    for (i = 0; i < 9; i = i + 1) begin
        @(negedge clk);
    end

    // ---------------------------------------------------------
    // Test Case 2: Saturation (All 1s)
    // Objective: Verify bit-width and ability to hold all 1s
    // ---------------------------------------------------------
    d = 1;
    for (i = 0; i < 9; i = i + 1) begin
        @(negedge clk);
    end

    // ---------------------------------------------------------
    // Test Case 3: Walking 0 in Field of 1s
    // Objective: Verify ability to clear bits and data path continuity
    // ---------------------------------------------------------
    // Insert a single 0. Expected q next: 8'h7F (01111111)
    d = 0;
    @(negedge clk);

    // Fill with 1s again to push the 0 out
    d = 1;
    for (i = 0; i < 9; i = i + 1) begin
        @(negedge clk);
    end

    // ---------------------------------------------------------
    // Test Case 4: Alternating Pattern 0xAA (10101010)
    // Objective: High frequency transitions to test setup/hold and bit independence
    // Note: q shifts right. Last d in is MSB.
    // To get 10101010 (MSB..LSB), input sequence must be 0,1,0,1,0,1,0,1 (Oldest..Newest)
    // ---------------------------------------------------------
    for (i = 0; i < 4; i = i + 1) begin
        d = 0; @(negedge clk);
        d = 1; @(negedge clk);
    end

    // ---------------------------------------------------------
    // Test Case 5: Alternating Pattern 0x55 (01010101)
    // Objective: Complementary pattern
    // ---------------------------------------------------------
    for (i = 0; i < 4; i = i + 1) begin
        d = 1; @(negedge clk);
        d = 0; @(negedge clk);
    end

    // Reset to 0 and hold
    d = 0;
    repeat(5) @(negedge clk);

    // 4. Handover
    $display("LLM: Tests Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

